     1	package com.pousada.api;
     2	
     3	import com.pousada.database.ReservationRepository;
     4	import com.pousada.database.RoomRepository;
     5	import com.pousada.model.Reservation;
     6	import com.pousada.model.Room;
     7	import com.pousada.service.FormattingService;
     8	import io.javalin.http.Context;
     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.time.format.DateTimeParseException;
    13	import java.util.List;
    14	
    15	public class ReportsEndpoint {
    16	  public static void getOccupancy(Context ctx) {
    17	    try {
    18	      String dateStr = ctx.queryParam("date");
    19	      if (dateStr == null || dateStr.isEmpty()) {
    20	        ctx.status(400).json(errorResponse("INVALID_REQUEST", "date parameter required"));
    21	        return;
    22	      }
    23	
    24	      LocalDate date = LocalDate.parse(dateStr);
    25	      List<Reservation> reservations = ReservationRepository.findConfirmedByDate(date);
    26	      List<Room> rooms = RoomRepository.findAll();
    27	
    28	      StringBuilder csv = new StringBuilder();
    29	      csv.append("room,type,reservation,check_in,check_out\n");
    30	
    31	      int occupiedCount = 0;
    32	      for (Room room : rooms) {
    33	        for (Reservation res : reservations) {
    34	          if (res.roomNumber == room.number) {
    35	            csv.append(room.number)
    36	                .append(",")
    37	                .append(room.type)
    38	                .append(",")
    39	                .append(res.id)
    40	                .append(",")
    41	                .append(FormattingService.formatCsvDate(res.checkIn))
    42	                .append(",")
    43	                .append(FormattingService.formatCsvDate(res.checkOut))
    44	                .append("\n");
    45	            occupiedCount++;
    46	            break;
    47	          }
    48	        }
    49	      }
    50	
    51	      csv.append("total,").append(occupiedCount).append("/").append(rooms.size());
    52	
    53	      ctx.contentType("text/csv; charset=utf-8").result(csv.toString());
    54	    } catch (DateTimeParseException e) {
    55	      ctx.status(400).json(errorResponse("INVALID_REQUEST", "Invalid date format"));
    56	    }
    57	  }
    58	
    59	  public static void getRevenue(Context ctx) {
    60	    try {
    61	      String monthStr = ctx.queryParam("month");
    62	      if (monthStr == null || monthStr.isEmpty()) {
    63	        ctx.status(400).json(errorResponse("INVALID_REQUEST", "month parameter required"));
    64	        return;
    65	      }
    66	
    67	      YearMonth month = YearMonth.parse(monthStr);
    68	      List<Reservation> reservations =
    69	          ReservationRepository.findByMonthAndNonCancelled(month.getYear(), month.getMonthValue());
    70	
    71	      StringBuilder csv = new StringBuilder();
    72	      csv.append("reservation,room,check_in,check_out,status,amount\n");
    73	
    74	      BigDecimal total = BigDecimal.ZERO;
    75	
    76	      for (Reservation res : reservations) {
    77	        BigDecimal amount = res.amountPaid;
    78	        if (res.refund != null) {
    79	          amount = amount.subtract(res.refund);
    80	        }
    81	
    82	        csv.append(res.id)
    83	            .append(",")
    84	            .append(res.roomNumber)
    85	            .append(",")
    86	            .append(FormattingService.formatCsvDate(res.checkIn))
    87	            .append(",")
    88	            .append(FormattingService.formatCsvDate(res.checkOut))
    89	            .append(",")
    90	            .append(res.status)
    91	            .append(",")
    92	            .append(FormattingService.formatCsv(amount))
    93	            .append("\n");
    94	
    95	        total = total.add(amount);
    96	      }
    97	
    98	      csv.append("total,,,,").append(FormattingService.formatCsv(total));
    99	
   100	      ctx.contentType("text/csv; charset=utf-8").result(csv.toString());
   101	    } catch (DateTimeParseException e) {
   102	      ctx.status(400).json(errorResponse("INVALID_REQUEST", "Invalid month format"));
   103	    }
   104	  }
   105	
   106	  private static java.util.Map<String, String> errorResponse(String code, String message) {
   107	    return java.util.Map.of("error", code, "message", message);
   108	  }
   109	}
