    18	  public static void createReservation(Context ctx) {
    19	    try {
    20	      JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
    21	
    22	      if (body == null) {
    23	        ctx.status(400).json(errorResponse("INVALID_REQUEST", "Invalid JSON"));
    24	        return;
    25	      }
    26	
    27	      if (!body.has("roomNumber")
    28	          || !body.has("guestName")
    29	          || !body.has("guestEmail")
    30	          || !body.has("guestCpf")
    31	          || !body.has("checkIn")
    32	          || !body.has("checkOut")
    33	          || !body.has("guests")
    34	          || !body.has("ratePlan")) {
    35	        ctx.status(400).json(errorResponse("INVALID_REQUEST", "Missing required fields"));
    36	        return;
    37	      }
    38	
    39	      ReservationService.CreateReservationRequest request =
    40	          new ReservationService.CreateReservationRequest();
    41	      request.roomNumber = body.get("roomNumber").getAsInt();
    42	      request.guestName = body.get("guestName").getAsString();
    43	      request.guestEmail = body.get("guestEmail").getAsString();
    44	      request.guestCpf = body.get("guestCpf").getAsString();
    45	      request.guests = body.get("guests").getAsInt();
    46	      request.ratePlan = body.get("ratePlan").getAsString();
    47	
    48	      try {
    49	        request.checkIn = LocalDate.parse(body.get("checkIn").getAsString());
    50	        request.checkOut = LocalDate.parse(body.get("checkOut").getAsString());
    51	      } catch (DateTimeParseException e) {
    52	        ctx.status(400).json(errorResponse("INVALID_REQUEST", "Invalid date format"));
    53	        return;
    54	      }
    55	
    56	      Reservation reservation = ReservationService.createReservation(request);
    57	      ctx.status(201).json(reservationToJson(reservation));
    58	    } catch (ReservationService.ApiException e) {
    59	      ctx.status(e.statusCode).json(errorResponse(e.code, e.getMessage()));
    60	    } catch (Exception e) {
    61	      ctx.status(400).json(errorResponse("INVALID_REQUEST", e.getMessage()));
    62	    }
    63	  }
