   174	      receipt.addProperty("guestCpf", res.guestCpf);
   175	      receipt.addProperty("roomNumber", res.roomNumber);
   176	      receipt.addProperty("roomType", roomType);
   177	      receipt.addProperty("checkIn", FormattingService.formatDate(res.checkIn));
   178	      receipt.addProperty("checkOut", FormattingService.formatDate(res.checkOut));
   179	      receipt.addProperty("nights", res.nights);
   180	      receipt.addProperty("subtotal", res.subtotal);
   181	      if (res.discount.compareTo(java.math.BigDecimal.ZERO) > 0) {
   182	        receipt.addProperty("discount", res.discount);
   183	      }
   184	      receipt.addProperty("total", res.total);
