   192	  private static JsonObject reservationToJson(Reservation reservation) {
   193	    JsonObject obj = new JsonObject();
   194	    obj.addProperty("id", reservation.id);
   195	    obj.addProperty("roomNumber", reservation.roomNumber);
   196	    obj.addProperty("guestName", reservation.guestName);
   197	    obj.addProperty("guestEmail", reservation.guestEmail);
   198	    obj.addProperty("guestCpf", reservation.guestCpf);
   199	    obj.addProperty("checkIn", FormattingService.formatCsvDate(reservation.checkIn));
   200	    obj.addProperty("checkOut", FormattingService.formatCsvDate(reservation.checkOut));
   201	    obj.addProperty("guests", reservation.guests);
   202	    obj.addProperty("ratePlan", reservation.ratePlan);
   203	    obj.addProperty("nights", reservation.nights);
   204	    obj.addProperty("subtotal", reservation.subtotal);
   205	    obj.addProperty("discount", reservation.discount);
   206	    obj.addProperty("total", reservation.total);
   207	    obj.addProperty("status", reservation.status);
   208	    obj.addProperty("amountPaid", reservation.amountPaid);
   209	    if (reservation.refund != null) {
   210	      obj.addProperty("refund", reservation.refund);
   211	    } else {
   212	      obj.add("refund", null);
   213	    }
   214	    return obj;
   215	  }
