     1	package com.pousada.service;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PricingService {
     9	  private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	  private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    11	
    12	  public static class PriceCalculation {
    13	    public final int nights;
    14	    public final BigDecimal subtotal;
    15	    public final BigDecimal discount;
    16	    public final BigDecimal total;
    17	
    18	    public PriceCalculation(BigDecimal subtotal, BigDecimal discount, int nights) {
    19	      this.nights = nights;
    20	      this.subtotal = subtotal;
    21	      this.discount = discount;
    22	      this.total = subtotal.subtract(discount);
    23	    }
    24	  }
    25	
    26	  public static PriceCalculation calculate(
    27	      LocalDate checkIn, LocalDate checkOut, BigDecimal nightlyRate, String ratePlan) {
    28	    int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    29	
    30	    BigDecimal subtotal = BigDecimal.ZERO;
    31	    LocalDate current = checkIn;
    32	
    33	    while (current.isBefore(checkOut)) {
    34	      BigDecimal nightPrice = nightlyRate;
    35	
    36	      if (isHighSeason(current)) {
    37	        nightPrice = nightPrice.multiply(HIGH_SEASON_MULTIPLIER);
    38	      }
    39	
    40	      nightPrice = roundHalfEven(nightPrice);
    41	      subtotal = subtotal.add(nightPrice);
    42	
    43	      current = current.plusDays(1);
    44	    }
    45	
    46	    subtotal = roundHalfEven(subtotal);
    47	
    48	    BigDecimal discount = BigDecimal.ZERO;
    49	    if ("NON_REFUNDABLE".equals(ratePlan)) {
    50	      discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
    51	      discount = roundHalfEven(discount);
    52	    }
    53	
    54	    BigDecimal total = subtotal.subtract(discount);
    55	
    56	    return new PriceCalculation(subtotal, discount, nights);
    57	  }
    58	
    59	  private static boolean isHighSeason(LocalDate date) {
    60	    Month month = date.getMonth();
    61	    int dayOfMonth = date.getDayOfMonth();
    62	
    63	    if (month == Month.JULY) {
    64	      return true;
    65	    }
    66	
    67	    if (month == Month.DECEMBER) {
    68	      return true;
    69	    }
    70	
    71	    if (month == Month.JANUARY || month == Month.FEBRUARY) {
    72	      return true;
    73	    }
    74	
    75	    return false;
    76	  }
    77	
    78	  public static BigDecimal roundHalfEven(BigDecimal value) {
    79	    return value.setScale(2, RoundingMode.HALF_EVEN);
    80	  }
    81	}
