    22	    PricingService.PriceCalculation pricing =
    23	        PricingService.calculate(checkIn, checkOut, nightlyRate, "STANDARD");
    24	
    25	    assertEquals(2, pricing.nights);
    26	    assertEquals(0, pricing.subtotal.compareTo(new BigDecimal("599.76")));
    27	    assertEquals(0, pricing.discount.compareTo(new BigDecimal("0.00")));
    28	    assertEquals(0, pricing.total.compareTo(new BigDecimal("599.76")));
