    41	    assertEquals(0, pricing.subtotal.compareTo(new BigDecimal("599.76")));
    42	    assertEquals(0, pricing.discount.compareTo(new BigDecimal("89.96")));
    43	    assertEquals(0, pricing.total.compareTo(new BigDecimal("509.80")));
