    61	    BigDecimal value = new BigDecimal("123.455");
    62	    BigDecimal rounded = PricingService.roundHalfEven(value);
    63	    assertEquals(0, rounded.compareTo(new BigDecimal("123.46")));
    64	
    65	    value = new BigDecimal("123.445");
    66	    rounded = PricingService.roundHalfEven(value);
    67	    assertEquals(0, rounded.compareTo(new BigDecimal("123.44")));
    68	  }
    69	}

